import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const dist=path.join(root,'dist');
const cfg=JSON.parse(fs.readFileSync(path.join(root,'site.config.json'),'utf8'));
const locales=['ar','en','fr'];
const domain=(process.env.SITE_URL||cfg.domain||'').trim().replace(/\/$/,'');
const contact=(process.env.CONTACT_EMAIL||cfg.contactEmail||'').trim();
const publisher=(process.env.ADSENSE_PUBLISHER_ID||cfg.adsensePublisherId||'').trim();
const adsEnabled=String(process.env.ENABLE_ADSENSE||cfg.enableAdsense||'false')==='true';
if(domain && !/^https:\/\/[a-z0-9.-]+(?::\d+)?(?:\/[a-z0-9._~-]+)*$/i.test(domain)) throw new Error('SITE_URL must be a full https:// URL, optionally with a project path');
const basePath=domain ? new URL(domain).pathname.replace(/\/$/,'') : '';
if (adsEnabled && !/^ca-pub-\d{16}$/.test(publisher)) throw new Error('Set a valid ca-pub-XXXXXXXXXXXXXXXX publisher ID before enabling ads');
const files=fs.readdirSync(path.join(root,'content/articles')).filter(x=>x.endsWith('.json'));
const articles=files.map(file=>JSON.parse(fs.readFileSync(path.join(root,'content/articles',file),'utf8'))).sort((a,b)=>b.date.localeCompare(a.date)||a.slug.localeCompare(b.slug));
const marketFeed=JSON.parse(fs.readFileSync(path.join(root,'content/feeds/latest.json'),'utf8'));
const marketCalendar=JSON.parse(fs.readFileSync(path.join(root,'content/calendar/events.json'),'utf8'));
