const staticCopy={
 ar:{
 about:['عن ربح لاب','ربح لاب منصة تعليمية مستقلة تهدف إلى مساعدة القراء على فهم الأدوات الرقمية والمهارات القابلة للتطبيق وحدود المخاطر المالية. لا نبيع وعوداً بالثراء السريع ولا نقدم توصيات استثمارية شخصية.','ننشر أدلة في ثلاثة مجالات متكاملة: تطوير مهارات العمل عبر الإنترنت، فهم مخاطر التداول، والاستفادة المسؤولة من الذكاء الاصطناعي.','تُعد المواد لأغراض تعليمية. نحرص على الأمثلة الواقعية، ونوضح الافتراضات والتكاليف والمخاطر، ونراجع المواد عند ظهور تغييرات جوهرية.'],
 editorial:['سياسة التحرير والمراجعة','نختار الموضوعات بناءً على الأسئلة العملية التي يواجهها المبتدئون وأصحاب المشاريع. الهدف أن يخرج القارئ بخطوات يمكن التحقق منها، لا بمجرد انطباع تسويقي.','نفصل بين الرأي والمعلومة، ولا نختلق تجارب شخصية أو نتائج أداء. نراجع الحسابات والمفاهيم الحساسة، ونفضل الروابط الرسمية عندما يتعلق الأمر بالسياسات والقوانين.','كل مقال يحمل تاريخ نشر وتحديث. إذا وجدت خطأ، يمكنك مراسلتنا لتقييمه وتصحيحه. لا يشترط أن يكون التحديث شاملاً؛ نعطي الأولوية لتصحيح المعلومات المؤثرة.','قد يساهم الذكاء الاصطناعي في تنظيم الأفكار أو التدقيق اللغوي، لكن نشر المادة ومراجعة المعطيات مسؤولية بشرية. الإعلانات المستقبلية لا تحدد ترتيب توصياتنا التحريرية.'],
 privacy:['سياسة الخصوصية','في النسخة الأساسية من الموقع لا نشغّل تحليلات خارجية أو إعلانات أو أدوات تتبع تسويقية. صفحات المحتوى وأدوات الحساب تعمل داخل متصفحك ولا ترسل القيم التي تدخلها إلينا.','قد يجمع مزود الاستضافة بيانات تقنية لازمة لتقديم الموقع وتأمينه، مثل عنوان IP وسجلات الأخطاء، وفق سياسته الخاصة. إن تواصلت معنا عبر البريد فسنتعامل مع رسالتك للرد على طلبك.','إذا فُعّلت Google AdSense لاحقاً، فقد تستخدم Google وشركاؤها ملفات تعريف الارتباط أو معرّفات أخرى لعرض الإعلانات وقياسها حسب الإعدادات والموافقات. سنحدّث هذه الصفحة ونفعّل أداة إدارة موافقة مناسبة قبل تشغيل الخدمات حيث تُطلب قانوناً.','لمعرفة خيارات Google الإعلانية يمكنك زيارة https://policies.google.com/technologies/ads. يمكنك الاستفسار عن البيانات عبر بريد التواصل المعلن بعد تفعيله.'],
 terms:['شروط الاستخدام','محتوى الموقع مخصص للتعلم العام. يجوز قراءته والاستفادة منه شخصياً مع احترام حقوق المؤلف وعدم نسخ المقالات بالكامل لإعادة نشرها دون إذن.','نحاول دقة المعلومات لكن المنتجات والسياسات والأسواق تتغير. يتحمل القارئ مسؤولية التحقق من ملاءمة المعلومات لحالته قبل اتخاذ قرارات مالية أو تجارية أو تقنية.','قد تتغير أو تتوقف بعض أجزاء الموقع لأغراض الصيانة والتطوير. الروابط الخارجية تعود إلى مواقع يتحكم فيها أصحابها ولا نضمن محتواها.','عند استخدام الأدوات المجانية، تحقق بنفسك من المدخلات والنتائج؛ فهي تقديرات مبسطة وليست برنامجاً محاسبياً أو استشارياً معتمداً.'],
 disclaimer:['إخلاء المسؤولية المالية والتقنية','التداول في الأدوات المالية، خصوصاً عقود الفروقات والأدوات ذات الرافعة، ينطوي على خطر خسارة رأس المال وقد تحدث خسائر تفوق التوقعات. المقالات والحاسبات ليست توصية شراء أو بيع ولا خطة استثمار شخصية.','أي حديث عن العمل الحر أو التسويق بالعمولة أو المنتجات الرقمية يشرح آليات عامة ولا يضمن دخلاً أو عملاء أو نجاحاً تجارياً. قد تكون هناك ضرائب ورسوم وشروط محلية تنطبق عليك.','أدوات الذكاء الاصطناعي قد ترتكب أخطاء أو تعرض معلومات غير محدثة. راجع النصوص والأكواد والنتائج قبل استخدامها، ولا ترفع معلومات حساسة إلى أدوات لا تعرف شروطها.','استعن بمختص مرخّص عند اتخاذ قرارات مالية أو قانونية أو ضريبية ذات أثر مهم.'],
 contact:['تواصل مع الفريق','نستقبل اقتراحات الموضوعات، وتصحيح المعلومات، والاستفسارات المتعلقة بالمحتوى أو حقوق النشر. قدّم رابط الصفحة ووصف الملاحظة لمساعدتنا على المتابعة.','لا نراجع المحافظ الاستثمارية الشخصية ولا نقدم إشارات تداول أو ضمانات أرباح. يرجى عدم إرسال كلمات مرور أو بيانات بنكية أو مستندات سرية عبر البريد.']},
 en:{
 about:['About RibhLab','RibhLab is an independent learning publication helping readers understand digital opportunities, practical skills and financial risk. We do not sell get-rich-quick promises or personalized investment signals.','Our three topics are earning online through genuine skills, understanding trading risks, and applying AI responsibly in real workflows.','Content is educational. We explain assumptions and costs, favor practical demonstrations and revise material when relevant facts change.'],
 editorial:['Editorial standards','We select topics for their practical usefulness to learners and small business builders. The reader should leave with verifiable steps instead of marketing slogans.','We distinguish information from opinion and do not fabricate tests, personal experience or performance data. We aim to verify important calculations and point to authoritative sources where applicable.','Articles show publication and update dates. Corrections can be requested by email and assessed on their merits. Priority goes to material inaccuracies.','AI may assist with outlining or language editing, but editorial responsibility remains human. Future advertisements will not determine our editorial conclusions.'],
 privacy:['Privacy policy','In this starter deployment, we do not load advertising, third-party analytics or marketing trackers. Our calculators run locally in your browser, and the figures you type are not transmitted to us.','Your hosting provider may process essential technical logs such as IP addresses for service delivery and security according to its policy. If you email us, we process your message to respond.','If Google AdSense is enabled later, Google and partners may use cookies or other identifiers to serve and measure advertisements, subject to applicable settings and consent. We will update this notice and configure a suitable consent-management solution where required before activating those services.','For Google advertising controls, see https://policies.google.com/technologies/ads. Contact us at the configured editorial email with any privacy enquiries.'],
 terms:['Terms of use','The site is for general education. You may read and use its guidance privately, but may not republish full articles without permission or misrepresent authorship.','Markets, tools and policies change. You are responsible for checking suitability before acting on financial, commercial or technical information.','Some features may change during maintenance. Third-party websites linked here are managed by their own publishers.','Free calculators produce simplified estimates only and are not certified accounting or professional advisory software.'],
 disclaimer:['Financial and technical disclaimer','Trading financial instruments, especially leveraged products and CFDs, carries substantial risk of losing capital. Guides and calculators are not trade recommendations or individualized investment advice.','Information about freelancing, affiliate publishing or digital products does not guarantee clients, revenue or business success. Taxes, fees and local restrictions may apply.','AI systems can invent facts, generate flawed code and expose confidential information if used carelessly. Verify outputs and platform privacy rules before operational use.','Seek qualified licensed professional advice for consequential investment, legal or tax decisions.'],
 contact:['Contact the editorial team','We welcome corrections, article ideas and content or copyright questions. Include the page link and a short explanation when reporting an issue.','We do not review personal investment portfolios, sell trading signals or promise earnings. Please do not email passwords, banking details or confidential documents.']},
 fr:{
 about:['À propos de RibhLab','RibhLab est un média pédagogique indépendant consacré aux compétences numériques, aux opportunités en ligne et à la compréhension des risques financiers. Aucune promesse de richesse facile ni de conseil personnalisé.','Nos sujets : développer des compétences freelance, comprendre les risques du trading et utiliser l’IA de façon responsable dans le travail.','Nos contenus sont éducatifs. Nous détaillons les hypothèses, les coûts et les limites, puis révisons les informations importantes lorsqu’elles évoluent.'],
 editorial:['Politique éditoriale','Nous choisissons des sujets qui répondent à des questions concrètes des lecteurs. Chaque dossier doit apporter des démarches vérifiables, pas des slogans publicitaires.','Nous distinguons les opinions des faits et n’inventons ni essais, ni témoignages, ni performances. Nous privilégions les sources officielles sur les points réglementaires.','Les articles affichent des dates de publication et de mise à jour. Les rectifications peuvent être proposées par e-mail et examinées.','L’IA peut aider à structurer ou relire un texte, mais la responsabilité éditoriale demeure humaine. Une publicité future ne dictera pas nos conclusions.'],
 privacy:['Politique de confidentialité','Dans cette version initiale, aucun service publicitaire, outil d’analyse externe ni traceur marketing n’est activé. Les calculatrices fonctionnent dans votre navigateur sans nous transmettre leurs données de saisie.','L’hébergeur peut traiter des journaux techniques indispensables, notamment les adresses IP, selon sa propre politique. Si vous écrivez à notre équipe, votre message sert à traiter votre demande.','Si AdSense est ajouté ultérieurement, Google et ses partenaires pourront utiliser des cookies ou identifiants pour diffuser et mesurer les publicités, dans le respect des règles et consentements applicables. Cette notice sera actualisée et une plateforme de consentement adaptée mise en place avant activation lorsque nécessaire.','Informations sur les technologies publicitaires Google : https://policies.google.com/technologies/ads. Pour toute question, utilisez l’adresse de contact configurée.'],
 terms:['Conditions d’utilisation','Les contenus sont fournis pour la formation générale. Vous pouvez les consulter, mais pas republier intégralement les articles sans autorisation ni en usurper la paternité.','Les marchés, logiciels et règles changent. Vérifiez toute information avant de prendre une décision financière, commerciale ou technique.','Certaines fonctionnalités peuvent évoluer. Les sites externes cités restent sous la responsabilité de leurs éditeurs.','Les calculateurs gratuits livrent des estimations simplifiées, et non des prestations professionnelles certifiées.'],
 disclaimer:['Avertissements financiers et techniques','Les marchés financiers, en particulier les CFD et instruments à effet de levier, présentent un risque important de perte en capital. Nos ressources n’offrent aucun signal ni conseil en investissement personnalisé.','Les méthodes de freelance, d’affiliation et de produits numériques ne garantissent ni chiffre d’affaires ni acquisition de clients. Frais, fiscalité et limitations locales peuvent s’appliquer.','Les outils d’IA peuvent se tromper ou générer du code dangereux. Vérifiez chaque résultat et les règles de confidentialité avant usage.','Pour des décisions importantes, consultez un professionnel qualifié selon le domaine.'],
 contact:['Contacter la rédaction','Nous accueillons les suggestions, corrections, questions éditoriales et demandes relatives aux droits d’auteur. Pour une correction, indiquez le lien et le passage concerné.','Nous ne proposons ni signaux de trading ni conseils sur portefeuille individuel. Ne transmettez aucun mot de passe ou document confidentiel.']}
};
const esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const urlFor=(l,a)=>`/${l}/${a.category}/${a.slug}/`;
const catUrl=(l,cat)=>`/${l}/${cat}/`;
const aPath=p=>p.replace(/^\//,'');
const idDate=s=>esc(new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{year:'numeric',month:'short',day:'numeric'}));
const icon=(name)=>({earning:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="6" y="12" width="36" height="28" rx="6" stroke="currentColor" stroke-width="2.5"/><path d="M16 13V9a4 4 0 014-4h8a4 4 0 014 4v4M6 23c10 7 26 7 36 0" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><path d="M22 25h4" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>',trading:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M7 39h34M10 29l8-9 8 5 12-15" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M30 10h8v8" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M11 33v6M21 31v8M31 25v14" stroke="currentColor" stroke-width="2.4"/></svg>',ai:'<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="12" y="12" width="24" height="24" rx="7" stroke="currentColor" stroke-width="2.6"/><path d="M20 21h.01M28 21h.01M19 28c2 3 8 3 10 0M19 4v8M29 4v8M19 36v8M29 36v8M4 19h8M4 29h8M36 19h8M36 29h8" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>'}[name]);
function relLinks(current,pathMap){return domain ? `<link rel="canonical" href="${esc(domain+pathMap[current])}">${locales.map(l=>`<link rel="alternate" hreflang="${l}" href="${esc(domain+pathMap[l])}">`).join('')}<link rel="alternate" hreflang="x-default" href="${esc(domain+pathMap.ar)}">` : '';}
function jsonScript(v){return JSON.stringify(v).replace(/</g,'\\u003c');}
function schemaFor(l,type,title,desc,route,article){let obj={'@context':'https://schema.org','@type':type==='article'?'Article':'WebPage',name:title,description:desc,inLanguage:l};if(domain)obj.url=domain+route;
if(type==='article'){obj.headline=title;obj.datePublished=article.date;obj.dateModified=article.updated;obj.author={'@type':'Organization',name:cfg.publisherName||'RibhLab Editorial Team'};obj.publisher={'@type':'Organization',name:'RibhLab'};obj.mainEntityOfPage=domain?domain+route:undefined;}
return `<script type="application/ld+json">${jsonScript(obj)}</script>`;}
function page(l,{title,desc,route,altroutes,content,type='page',article,active=''}){
 const t=i18n[l],rtl=l==='ar',pathMap=altroutes||Object.fromEntries(locales.map(n=>[n,route.replace(/^\/[a-z]{2}\//,`/${n}/`)]));
 const switches=locales.map(n=>`<a href="${pathMap[n]}" lang="${n}" hreflang="${n}" ${l===n?'aria-current="true" class="selected"':''}>${({ar:'العربية',en:'English',fr:'Français'})[n]}</a>`).join('');
 const nav=['earning','trading','ai','tools'].map(k=>`<a href="/${l}/${k}/" ${active===k?'aria-current="page" class="nav-current"':''}>${esc(t[k])}</a>`).join('');
 const ads=adsEnabled?`<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${publisher}" crossorigin="anonymous"></script>`:'';
 const s=`<!doctype html><html lang="${l}" dir="${rtl?'rtl':'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1832"><meta name="color-scheme" content="light"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:site_name" content="RibhLab"><meta property="og:url" content="${esc(domain+route)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(desc)}"><meta name="twitter:image" content="${esc(domain+'/assets/og-cover.png')}"><meta property="og:type" content="${type==='article'?'article':'website'}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:image" content="${esc((domain||'')+'/assets/og-cover.png')}"><meta property="og:image:alt" content="RibhLab — Knowledge hub"><meta property="og:locale" content="${({ar:'ar_MA',en:'en_US',fr:'fr_FR'})[l]}">${type==='article'?`<meta property="article:published_time" content="${esc(article.date)}"><meta property="article:modified_time" content="${esc(article.updated)}">`: ''}${relLinks(l,pathMap)}<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css">${schemaFor(l,type,title,desc,route,article)}${ads}</head><body data-lang="${l}"><a class="skip" href="#main">${esc(t.skip)}</a><div class="topbar"><div class="shell topbar-inner"><span class="topbar-dot"></span><span>${esc(t.tagline)}</span><span class="topbar-end">AR &nbsp;·&nbsp; EN &nbsp;·&nbsp; FR</span></div></div><header class="header"><div class="shell nav-inner"><a href="/${l}/" class="brand" aria-label="${esc(t.name)}"><span class="brand-symbol">R<span>.</span></span><span class="brand-copy"><strong>RibhLab</strong><small>${esc(t.tagline)}</small></span></a><nav class="nav-links" id="site-nav" aria-label="${esc(t.menu)}"><a href="/${l}/markets/" ${active==='markets'?'aria-current="page" class="nav-current"':''}>${esc(marketLabels[l].title)}</a>${nav}</nav><div class="nav-actions"><button class="icon-button search-toggle" data-search-open aria-label="${esc(t.searchShortcut)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/></svg></button><div class="lang-menu" aria-label="${esc(t.language)}">${switches}</div><button class="icon-button mobile-menu" aria-label="${esc(t.menu)}" aria-controls="site-nav" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button></div></div></header><main id="main">${content}</main><footer class="footer"><div class="shell"><div class="footer-grid"><div><a href="/${l}/" class="footer-brand"><span class="brand-symbol">R<span>.</span></span><strong>RibhLab</strong></a><p class="footer-desc">${esc(t.footerDesc)}</p><div class="footer-languages">${switches}</div></div><div><h3>${esc(t.learn)}</h3><a href="${catUrl(l,'earning')}">${esc(t.earning)}</a><a href="${catUrl(l,'trading')}">${esc(t.trading)}</a><a href="${catUrl(l,'ai')}">${esc(t.ai)}</a><a href="/${l}/tools/">${esc(t.tools)}</a></div><div><h3>${esc(t.quickLinks)}</h3><a href="/${l}/about/">${esc(t.about)}</a><a href="/${l}/editorial/">${esc(t.editorial)}</a><a href="/${l}/contact/">${esc(t.contact)}</a><a href="/${l}/disclaimer/">${esc(t.disclaimer)}</a></div><div><h3>${esc(t.privacy)}</h3><a href="/${l}/privacy/">${esc(t.privacy)}</a><a href="/${l}/terms/">${esc(t.terms)}</a><p class="footer-desc smaller">${esc(t.adDisclosure)}</p></div></div><div class="footer-bottom"><span>© ${new Date().getUTCFullYear()} RibhLab. ${esc(t.copyright)}.</span><span>${esc(t.noReturn)}</span></div></div></footer><dialog class="search-modal" id="search-modal" aria-labelledby="search-title"><div class="search-head"><h2 id="search-title">${esc(t.searchTitle)}</h2><button class="icon-button search-close" data-search-close aria-label="Close">×</button></div><label class="visually-hidden" for="site-search">${esc(t.search)}</label><input id="site-search" type="search" placeholder="${esc(t.search)}" autocomplete="off" data-search-input><div class="search-results" data-search-results role="status" aria-live="polite"></div></dialog><script>window.RIBHLAB_BASE_PATH=${jsonScript(basePath)};window.RIBHLAB_I18N=${jsonScript({noResults:t.noResults,minutes:t.minutes,lang:l})};</script><script src="/assets/app.js" defer></script></body></html>`;
 const filepath=path.join(dist,aPath(route),'index.html');fs.mkdirSync(path.dirname(filepath),{recursive:true});fs.writeFileSync(filepath,s);
 routes.push({route,lastmod:article?.updated||'2026-10-25'});
}
const routes=[];
function articleCard(l,a,feature=false){const t=i18n[l],tr=a.translations[l];return `<article class="article-card ${feature?'card-featured':''}"><a class="card-link" href="${urlFor(l,a)}" aria-label="${esc(tr.title)}"><div class="card-art art-${a.category}"><span class="card-art-icon">${icon(a.category)}</span><span class="card-art-label">${esc(t[a.category])}</span><span class="card-art-corner">↗</span></div><div class="card-body"><div class="card-meta"><span class="category-kicker">${esc(t[a.category])}</span><span>${idDate(a.updated)}</span></div><h3>${esc(tr.title)}</h3><p>${esc(tr.excerpt)}</p><span class="read-more">${esc(t.read)} <span aria-hidden="true">↗</span></span></div></a></article>`;}
function categoryGrid(l){const t=i18n[l];return `<div class="category-grid">${['earning','trading','ai'].map((cat,k)=>`<a class="topic-card topic-${cat}" href="${catUrl(l,cat)}"><div class="topic-top"><span class="topic-symbol">${icon(cat)}</span><span class="topic-number">0${k+1}</span></div><h3>${esc(t[cat])}</h3><p>${esc(t[cat+'Desc'])}</p><span class="topic-cta">${esc(t.viewCategory)} <b>↗</b></span></a>`).join('')}</div>`;}
function home(l){const t=i18n[l],featured=articles.filter(x=>x.featured),rest=articles.filter(x=>!x.featured).slice(0,6);
const panel=`<div class="hero-visual" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-center"><span class="center-kicker">RIBHLAB / KNOWLEDGE HUB</span><div class="mini-chart"><i style="height:36%"></i><i style="height:57%"></i><i style="height:42%"></i><i style="height:78%"></i><i style="height:64%"></i><i style="height:90%"></i></div><strong>Learn <span>·</span> Test <span>·</span> Grow</strong></div><div class="floating-chip chip-one"><span>↗</span> DIGITAL SKILLS</div><div class="floating-chip chip-two"><span>✦</span> AI WORKFLOWS</div><div class="floating-chip chip-three"><span>◈</span> RISK FIRST</div></div>`;
 const content=`<section class="hero"><div class="shell hero-grid"><div class="hero-copy"><div class="eyebrow"><span class="eyebrow-line"></span>${esc(t.heroEyebrow)}</div><h1><span>${esc(t.hero1)}</span><span>${esc(t.hero2)}</span><em>${esc(t.hero3)}</em></h1><p>${esc(t.heroDesc)}</p><div class="hero-buttons"><a class="btn btn-primary" href="#categories">${esc(t.explore)}<span aria-hidden="true">↗</span></a><a class="btn btn-outline" href="/${l}/editorial/">${esc(t.ctaAbout)}</a></div><div class="hero-trust"><span><i>✓</i>${esc(t.trust2)}</span><span><i>✓</i>${esc(t.trust3)}</span></div></div>${panel}</div><div class="hero-bottom-line"></div></section><section class="credibility"><div class="shell credibility-grid"><div><strong>03</strong><span>${esc(t.trust1)}</span></div><div><strong>100%</strong><span>${esc(t.trust2)}</span></div><div><strong>0</strong><span>${esc(t.trust3)}</span></div><div><strong>↔</strong><span>${esc(t.trust4)}</span></div></div></section><section id="categories" class="section shell"><div class="section-head"><div><span class="section-kicker">01 / TOPICS</span><h2>${esc(t.categoryTitle)}</h2><p>${esc(t.categoryDesc)}</p></div></div>${categoryGrid(l)}</section><section class="section shell"><div class="market-promo"><div><span class="section-kicker">RIBHLAB / MARKET PULSE</span><h2>${esc(marketLabels[l].title)}</h2><p>${esc(marketLabels[l].desc)}</p></div><a class="btn btn-primary" href="/${l}/markets/">${esc(marketLabels[l].title)} ↗</a></div></section><section class="section section-sand"><div class="shell"><div class="section-head split"><div><span class="section-kicker">02 / EDITOR'S PICKS</span><h2>${esc(t.featured)}</h2><p>${esc(t.latestDesc)}</p></div><a class="text-link" href="#latest">${esc(t.viewAll)} <span>↗</span></a></div><div class="article-grid">${featured.map(a=>articleCard(l,a)).join('')}</div></div></section><section class="section shell" id="latest"><div class="section-head"><div><span class="section-kicker">03 / LIBRARY</span><h2>${esc(t.latest)}</h2><p>${esc(t.latestDesc)}</p></div></div><div class="article-grid">${rest.map(a=>articleCard(l,a)).join('')}</div></section><section class="method-section"><div class="shell method-grid"><div class="method-heading"><span class="section-kicker">04 / OUR METHOD</span><h2>${esc(t.learnTitle)}</h2><p>${esc(t.learnDesc)}</p><a href="/${l}/editorial/" class="text-link">${esc(t.ctaAbout)} ↗</a></div><div class="method-steps">${[1,2,3].map(n=>`<div class="method-step"><span>0${n}</span><div><h3>${esc(t['step'+n])}</h3><p>${esc(t['step'+n+'d'])}</p></div></div>`).join('')}</div></div></section><section class="section shell"><div class="tools-banner"><div><span class="banner-icon">⌘</span><h2>${esc(t.toolsCall)}</h2><p>${esc(t.toolsCallDesc)}</p></div><a class="btn btn-light" href="/${l}/tools/">${esc(t.toolsOpen)} ↗</a></div></section>`;
 page(l,{title:t.homeTitle,desc:t.homeDescription,route:`/${l}/`,content:content+`<div class="shell">${sharingBar(l)}</div>`});
}
function catPage(l,cat){const t=i18n[l],items=articles.filter(a=>a.category===cat),content=`<section class="page-hero compact-hero"><div class="shell"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/${l}/">${esc(t.navHome)}</a><span>/</span><span>${esc(t[cat])}</span></nav><div class="cat-page-icon">${icon(cat)}</div><span class="section-kicker">RIBHLAB / TOPIC</span><h1>${esc(t[cat])}</h1><p>${esc(t[cat+'Desc'])}</p></div></section><section class="section shell"><div class="section-head"><h2>${esc(t.allIn)} <span class="count-chip">${items.length}</span></h2></div><div class="article-grid">${items.map(a=>articleCard(l,a)).join('')}</div></section><section class="shell tiny-note">${esc(t.noReturn)}</section>`;
 page(l,{title:`${t[cat]} | RibhLab`,desc:t[cat+'Desc'],route:catUrl(l,cat),content,active:cat});
}
function sharingBar(l){
 const shareTitle=({ar:'شارك هاد المقال مع الآخرين',en:'Share this article',fr:'Partager cet article'})[l];
 const btn=({ar:'مشاركة من الهاتف',en:'Share from device',fr:'Partager depuis mon appareil'})[l];
 const copy=({ar:'نسخ الرابط',en:'Copy link',fr:'Copier le lien'})[l];
 return `<section class="sharing-bar" aria-label="${esc(shareTitle)}"><h2>${esc(shareTitle)}</h2><div class="sharing-actions">${['WhatsApp','Facebook','X','LinkedIn','Telegram','Pinterest','Reddit','Email'].map(network=>`<a class="share-pill share-${network.toLowerCase()}" data-share-network="${network}" target="_blank" rel="noopener noreferrer" href="#" aria-label="${esc(shareTitle)} — ${network}">${network}</a>`).join('')}<button class="share-pill share-native" type="button" data-share-native>${esc(btn)}</button><button class="share-pill share-copy" type="button" data-share-copy>${esc(copy)}</button></div><p class="sharing-note">${esc(({ar:'يمكنك مشاركة الرابط كذلك في Instagram وTikTok وSnapchat عبر نسخ الرابط أو قائمة المشاركة.',en:'For Instagram, TikTok and Snapchat, copy the URL or use your device’s share menu.',fr:'Pour Instagram, TikTok et Snapchat, copiez le lien ou utilisez le menu de partage de votre appareil.'})[l])}</p></section>`;
}
function makeArticle(l,a){const t=i18n[l],tr=a.translations[l];let toc=tr.sections.map((s,i)=>`<a href="#part-${i+1}"><span>0${i+1}</span>${esc(s.heading)}</a>`).join('');
 const sections=tr.sections.map((s,i)=>`<section id="part-${i+1}" class="article-block"><h2>${esc(s.heading)}</h2>${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}${s.bullets?.length?`<ul class="checklist">${s.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`:''}</section>`).join('');
 const similar=articles.filter(b=>b.category===a.category&&b.slug!==a.slug).slice(0,2);
 const content=`<section class="article-hero"><div class="shell article-hero-inner"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/${l}/">${esc(t.navHome)}</a><span>/</span><a href="${catUrl(l,a.category)}">${esc(t[a.category])}</a><span>/</span><span>${esc(tr.title)}</span></nav><div class="article-hero-heading"><span class="article-category-tag">${esc(t[a.category])}</span><h1>${esc(tr.title)}</h1><p>${esc(tr.excerpt)}</p><div class="article-byline"><span class="editor-avatar">R.</span><div><strong>${esc(t.team)}</strong><span>${esc(t.updated)}: <time datetime="${esc(a.updated)}">${idDate(a.updated)}</time></span></div></div></div></div></section><div class="shell article-layout"><article class="article-content"><p class="lead">${esc(tr.lead)}</p>${a.category==='trading'?`<aside class="disclaimer-inline"><strong>${esc(t.important)}</strong><p>${esc(t.tradingNote)}</p></aside>`:''}${sections}${sharingBar(l)}<div class="article-end-note"><strong>${esc(t.important)}</strong><p>${esc(t.noReturn)}</p><a href="/${l}/disclaimer/">${esc(t.disclaimer)} ↗</a></div></article><aside class="article-sidebar"><div class="toc-card"><span class="toc-label">${esc(t.index)}</span>${toc}</div><div class="sidebar-help"><span>✦</span><p>${esc(t.noReturn)}</p></div></aside></div><section class="section shell related-section"><div class="section-head"><h2>${esc(t.related)}</h2></div><div class="article-grid">${similar.map(x=>articleCard(l,x)).join('')}</div></section>`;
 const route=urlFor(l,a);page(l,{title:`${tr.title} | RibhLab`,desc:tr.excerpt,route,altroutes:Object.fromEntries(locales.map(n=>[n,urlFor(n,a)])),content,type:'article',article:a,active:a.category});
}

function marketPulse(l){
 const words=marketLabels[l],future=(marketCalendar.events||[]).filter(x=>x.date>=new Date().toISOString().slice(0,10));
 const sourceLinks=[['Federal Reserve','https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm'],['BLS','https://www.bls.gov/schedule/2026/'],['European Central Bank','https://www.ecb.europa.eu/press/calendars/mgcgc/html/index.en.html'],['Bank of Japan','https://www.boj.or.jp/en/about/calendar/index.htm'],['China NBS','https://www.stats.gov.cn/english/PressRelease/index.html'],['World Gold Council','https://www.gold.org/goldhub/research']];
 const topics={crypto:'Crypto',new_tokens:'New tokens',gold:'Gold',us_macro:'US macro',europe:'Europe',japan:'Japan',china:'China',geopolitics:'Geopolitics',ai_future:'AI and future',digital_income:'Digital income'};
 const headlines=(marketFeed.items||[]).filter(x=>x.title&&/^https:\/\//.test(x.url)).slice(0,80);
 const filterBar='<div class="pulse-filters"><button class="pulse-filter current" type="button" data-pulse-filter="all">All</button>'+Object.entries(topics).map(([key,name])=>'<button class="pulse-filter" type="button" data-pulse-filter="'+key+'">'+esc(name)+'</button>').join('')+'</div>';
 const cards=headlines.map(x=>'<article class="pulse-card" data-pulse-topic="'+esc(x.topic)+'"><small>'+esc(topics[x.topic]||x.topic)+' · '+esc(x.publishedAt.slice(0,10))+'</small><h3>'+esc(x.title)+'</h3><p>'+esc(x.source)+'</p><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer nofollow">'+esc(words.visit)+' ↗</a></article>').join('');
 const schedule=future.map(x=>'<article class="pulse-event"><time datetime="'+esc(x.date)+'">'+esc(x.date)+'</time><div><strong>'+esc(x.title[l]||x.title.en)+'</strong><p>'+esc(x.country)+' · '+esc(x.time)+'</p></div><a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">'+esc(words.visit)+' ↗</a></article>').join('');
 const links=sourceLinks.map(([name,url])=>'<a href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+esc(name)+' ↗</a>').join('');
 const body='<section class="page-hero"><div class="shell"><span class="section-kicker">SOURCE-ATTRIBUTED / MARKETS</span><h1>'+esc(words.head)+'</h1><p>'+esc(words.desc)+'</p><a class="btn btn-primary" href="#economic-calendar">'+esc(words.calendar)+' ↗</a></div></section>'+
 '<section class="section shell"><div class="section-head"><div><h2>'+esc(words.title)+'</h2><p>'+esc(words.note)+'</p><small>'+esc(words.last)+': '+esc(marketFeed.fetchedAt)+' UTC</small></div></div>'+filterBar+'<div class="pulse-grid">'+cards+'</div><p class="pulse-risk">⚠ '+esc(words.warning)+'</p></section>'+
 '<section class="section section-sand" id="economic-calendar"><div class="shell"><div class="section-head"><div><h2>'+esc(words.calendar)+'</h2><p>'+esc(words.note)+'</p></div></div><div class="pulse-events">'+(schedule||'<p>'+esc(words.note)+'</p>')+'</div><div class="pulse-sources">'+links+'</div></div></section><div class="shell">'+sharingBar(l)+'</div>';
 page(l,{title:words.head+' | RibhLab',desc:words.desc,route:'/'+l+'/markets/',content:body,active:'markets'});
}

function staticPage(l,key){const t=i18n[l],c=staticCopy[l][key];let sections=c.slice(1).map(p=>`<p>${esc(p)}</p>`).join('');if(key==='contact')sections+=`<div class="contact-box"><span class="contact-illustration">✉</span><h2>${esc(t.contactInfo)}</h2><p>${esc(t.emailText)}</p>${contact?`<a class="contact-email" href="mailto:${esc(contact)}">${esc(contact)}</a>`:`<p class="notice-setup">${esc(t.contactPending)}</p>`}</div>`;
if(key==='privacy')sections+=`<p><a href="https://policies.google.com/technologies/ads" target="_blank" rel="noopener noreferrer">Google — Advertising Technologies ↗</a></p>`;
 const content=`<section class="page-hero"><div class="shell"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/${l}/">${esc(t.navHome)}</a><span>/</span><span>${esc(c[0])}</span></nav><span class="section-kicker">RIBHLAB / INFORMATION</span><h1>${esc(c[0])}</h1></div></section><div class="shell prose-layout"><div class="prose-page">${sections}<div class="policy-updated">${esc(t.updated)}: ${idDate('2026-10-25')}</div></div></div>`;
 page(l,{title:`${c[0]} | RibhLab`,desc:c[1],route:`/${l}/${key}/`,content});
}
function toolPage(l){const t=i18n[l],content=`<section class="page-hero"><div class="shell"><nav class="breadcrumbs"><a href="/${l}/">${esc(t.navHome)}</a><span>/</span><span>${esc(t.tools)}</span></nav><span class="section-kicker">RIBHLAB / INTERACTIVE LAB</span><h1>${esc(t.toolsTitle)}</h1><p>${esc(t.toolsDesc)}</p></div></section><div class="shell tool-layout"><section class="tool-card" id="risk-tool"><div class="tool-tag">01 / RISK</div><h2>${esc(t.riskTitle)}</h2><div class="tool-form"><label>${esc(t.capital)}<input type="number" id="risk-capital" min="0" step="0.01" value="10000"></label><label>${esc(t.riskPct)}<input type="number" id="risk-percent" min="0" max="100" step="0.1" value="1"></label><label>${esc(t.currency)}<select id="risk-currency"><option value="MAD">MAD</option><option value="USD">USD</option><option value="EUR">EUR</option></select></label></div><div class="tool-result"><span>${esc(t.riskOutput)}</span><strong id="risk-result" aria-live="polite">100.00 MAD</strong></div><p class="tool-hint">${esc(t.riskHint)}</p></section><section class="tool-card" id="fee-tool"><div class="tool-tag">02 / FREELANCE</div><h2>${esc(t.feeTitle)}</h2><div class="tool-form"><label>${esc(t.hours)}<input type="number" id="fee-hours" min="0" step="0.5" value="8"></label><label>${esc(t.hourRate)}<input type="number" id="fee-hourly" min="0" step="1" value="150"></label><label>${esc(t.expenses)}<input type="number" id="fee-expenses" min="0" step="1" value="100"></label><label>${esc(t.feePct)}<input type="number" id="fee-platform" min="0" max="99" step="0.1" value="10"></label></div><div class="tool-result"><span>${esc(t.priceResult)}</span><strong id="fee-result" aria-live="polite">1,444.44</strong></div><p class="tool-hint">${esc(t.priceHint)}</p></section><section class="tool-card tool-wide" id="prompt-tool"><div class="tool-tag">03 / AI PROMPT BUILDER</div><h2>${esc(t.promptTitle)}</h2><div class="tool-form"><label>${esc(t.goal)}<input id="prompt-goal" placeholder="${esc(t.promptExample)}"></label><label>${esc(t.context)}<textarea id="prompt-context" rows="3"></textarea></label><label>${esc(t.constraints)}<textarea id="prompt-constraints" rows="3"></textarea></label><label>${esc(t.format)}<input id="prompt-format"></label></div><div class="prompt-controls"><button class="btn btn-primary" id="create-prompt" type="button">${esc(t.buildPrompt)} ↗</button><button class="btn btn-neutral" id="copy-prompt" type="button">${esc(t.copy)}</button></div><label class="visually-hidden" for="prompt-output">Prompt</label><textarea readonly rows="8" id="prompt-output" class="prompt-result" aria-live="polite"></textarea></section></div><div class="shell tiny-note">${esc(t.noReturn)}</div>`;
 page(l,{title:`${t.tools} | RibhLab`,desc:t.toolsDesc,route:`/${l}/tools/`,content,active:'tools'});
}
fs.rmSync(dist,{recursive:true,force:true});fs.mkdirSync(path.join(dist,'assets'),{recursive:true});
for(const f of ['style.css','app.js','favicon.svg','og-cover.svg','og-cover.png'])fs.copyFileSync(path.join(root,'src',f),path.join(dist,'assets',f));
fs.cpSync(path.join(root,'admin'),path.join(dist,'admin'),{recursive:true});
fs.cpSync(path.join(root,'public'),dist,{recursive:true,force:true});
for(const l of locales){home(l);marketPulse(l);for(const cat of ['earning','trading','ai'])catPage(l,cat);for(const a of articles)makeArticle(l,a);for(const key of ['about','editorial','contact','privacy','terms','disclaimer'])staticPage(l,key);toolPage(l);
 fs.writeFileSync(path.join(dist,'assets',`search-${l}.json`),JSON.stringify(articles.map(a=>({title:a.translations[l].title,excerpt:a.translations[l].excerpt,url:basePath+urlFor(l,a),category:i18n[l][a.category],search:[a.translations[l].title,a.translations[l].excerpt,a.translations[l].lead].join(' ')}))));
}
fs.writeFileSync(path.join(dist,'index.html'),'<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="refresh" content="0; url=/ar/"><title>RibhLab</title></head><body><a href="/ar/">RibhLab العربية</a> · <a href="/en/">English</a> · <a href="/fr/">Français</a></body></html>');
fs.writeFileSync(path.join(dist,'404.html'),'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>404 | RibhLab</title><link rel="stylesheet" href="/assets/style.css"></head><body class="error-page"><h1>404</h1><p>Page not found · الصفحة غير موجودة · Page introuvable</p><a class="btn btn-primary" href="/ar/">Return home</a></body></html>');
const allRoutes=routes.map(x=>x.route);
fs.writeFileSync(path.join(dist,'robots.txt'),`User-agent: *\nAllow: /\nDisallow: /admin/\n${domain?'Sitemap: '+domain+'/sitemap.xml\n':''}`);
if(domain){fs.writeFileSync(path.join(dist,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">'+routes.map(x=>{const translations=locales.map(l=>`<xhtml:link rel="alternate" hreflang="${l}" href="${esc(domain+x.route.replace(/^\/[a-z]{2}\//,`/${l}/`))}"/>`).join('');return `<url><loc>${esc(domain+x.route)}</loc><lastmod>${x.lastmod}</lastmod>${translations}</url>`;}).join('')+'</urlset>');}
if(/^ca-pub-(\d{16})$/.test(publisher))fs.writeFileSync(path.join(dist,'ads.txt'),`google.com, pub-${publisher.slice(7)}, DIRECT, f08c47fec0942fa0\n`);
console.log(`Built ${routes.length} content pages from ${articles.length} tri-lingual articles. Domain ${domain||'not configured (set SITE_URL before deployment)'}. Ads ${adsEnabled?'enabled':'disabled'}.`);

// GitHub Pages project sites serve the site under /<repository>, not the domain root.
if(basePath){
 function visit(dir){return fs.readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?visit(path.join(dir,e.name)):[path.join(dir,e.name)]);}
 for(const file of visit(dist).filter(f=>f.endsWith('.html'))){
  let html=fs.readFileSync(file,'utf8');
  html=html.replace(/(\b(?:href|src)=\")\/(?!\/)/g,(_,start)=>start+basePath+'/');
  html=html.replace(/(http-equiv=\"refresh\" content=\"0; url=)\/(?!\/)/g,(_,start)=>start+basePath+'/');
  fs.writeFileSync(file,html);
 }
}
